SELECT json_object('section','sched_context','row',json_object('id',id,'ts',ts,'dur',dur,'cpu',cpu,'utid',utid,'priority',priority,'end_state',end_state)) AS payload FROM sched WHERE ts<1032236552522905 AND ts+dur>1032236378513990 AND dur>=0;
