SELECT json_object('section','counts','row',json_object('source','sched_systemwide','count',COUNT(*),'first_ts',MIN(ts),'last_ts',MAX(ts))) AS payload FROM sched WHERE ts>=1032151343301613 AND ts<1032251343301613;
SELECT json_object('section','counts','row',json_object('source','perf_source_'||perf_session_id,'count',COUNT(*),'unwind_errors',SUM(unwind_error IS NOT NULL),'with_stack',COUNT(callsite_id),'first_ts',MIN(ts),'last_ts',MAX(ts))) AS payload FROM perf_sample WHERE ts>=1032151343301613 AND ts<1032251343301613 GROUP BY perf_session_id;
SELECT json_object('section','stats','row',json_object('name',name,'idx',idx,'severity',severity,'source',source,'value',value)) AS payload FROM stats WHERE severity IN ('error','data_loss') OR name GLOB '*lost*' OR name GLOB '*overrun*' OR name GLOB '*dropped*';